-- Spanish curriculum (PLAN-multilingua.md, PR 8): 24 chapters A1-B2 x 4 lessons, same structure as the English one.
-- Titles and descriptions in Italian (the native language); grammar_focus and focus in English, for the prompts.
-- Written once and reviewed; the lessons themselves are generated (and shared) by the `lesson` function.

insert into public.chapters (language, level, sort_order, slug, title, description_it, grammar_focus) values
  ('es', 'A1', 1, 'a1-ser', 'Presentarsi', 'Il verbo ser, i saluti, le nazionalità, i numeri e la famiglia.', 'verb ser (present); subject pronouns; tú vs usted; greetings; countries and nationalities; numbers; tener for age; possessive adjectives'),
  ('es', 'A1', 2, 'a1-articulos', 'Le cose intorno a me', 'Articoli, genere, plurali e hay.', 'definite and indefinite articles (el/la/los/las, un/una/unos/unas); gender of nouns; plurals; hay vs está/están; prepositions of place'),
  ('es', 'A1', 3, 'a1-presente', 'La mia giornata', 'Il presente dei verbi regolari e i verbi riflessivi.', 'present tense of regular -ar, -er, -ir verbs; reflexive verbs for the daily routine; telling the time; days; adverbs of frequency'),
  ('es', 'A1', 4, 'a1-preguntas', 'Domande e negazioni', 'Fare domande, rispondere e dire cosa piace.', 'questions and question words with accents; negation no / nunca / nada / nadie; gustar and encantar; stem-changing verbs e>ie (preferir, querer)'),
  ('es', 'A1', 5, 'a1-irregulares', 'Andare, fare, potere', 'I verbi irregolari più comuni, l''imperativo e le indicazioni.', 'irregular present of ir, hacer, poder, querer, tener, venir; stem-changing verbs o>ue; imperative (tú, usted); asking for and giving directions'),
  ('es', 'A1', 6, 'a1-estar', 'Che cosa stai facendo?', 'Estar + gerundio, ser o estar, il tempo e i vestiti.', 'estar + gerundio; ser vs estar (basic uses); weather expressions with hace, hay, está; clothes; adjective agreement and colours'),
  ('es', 'A2', 1, 'a2-indefinido', 'Ieri', 'Il pretérito indefinido dei verbi regolari e le espressioni di tempo.', 'pretérito indefinido of regular verbs; ir/ser and hacer in the indefinido; past time expressions (ayer, el año pasado, hace + time)'),
  ('es', 'A2', 2, 'a2-irregulares-pasado', 'Raccontare il passato', 'I passati irregolari e come raccontare un viaggio.', 'irregular pretérito indefinido (tener, estar, poder, poner, decir, traer, venir); spelling changes (-car, -gar, -zar); sequencing words'),
  ('es', 'A2', 3, 'a2-cantidades', 'Cibo e quantità', 'Le quantità, i pronomi diretti e ordinare al ristorante.', 'quantities (mucho, poco, bastante, demasiado, un kilo de); direct object pronouns lo/la/los/las; ordering food; querría / me pone'),
  ('es', 'A2', 4, 'a2-comparativos', 'Fare confronti', 'Comparativi, superlativi e le forme irregolari.', 'comparatives más/menos ... que, tan ... como, tanto/a/os/as ... como; superlatives el/la más ...; mejor/peor/mayor/menor; -ísimo'),
  ('es', 'A2', 5, 'a2-imperfecto', 'Com''era una volta', 'L''imperfetto per descrivere e per le abitudini nel passato.', 'pretérito imperfecto formation (regular and ser, ir, ver); imperfecto for descriptions and habits; imperfecto vs indefinido'),
  ('es', 'A2', 6, 'a2-perfecto', 'Esperienze', 'Il pretérito perfecto per le esperienze e le azioni recenti.', 'pretérito perfecto (haber + participle); irregular participles; ya / todavía no / alguna vez / nunca; pretérito perfecto vs indefinido'),
  ('es', 'B1', 1, 'b1-futuro', 'Il futuro', 'Il futuro semplice, le condizioni reali e cuando + congiuntivo.', 'futuro simple of regular and irregular verbs; futuro for predictions and suppositions; si + presente, futuro; cuando + presente de subjuntivo'),
  ('es', 'B1', 2, 'b1-condicional', 'Se fossi...', 'Il condizionale: desideri, cortesia, consigli e ipotesi.', 'condicional simple; polite requests (¿podría...?); advice (deberías, yo que tú); si + imperfecto de subjuntivo, condicional'),
  ('es', 'B1', 3, 'b1-subjuntivo', 'Il congiuntivo', 'Il congiuntivo presente per desideri, emozioni e opinioni.', 'presente de subjuntivo (regular and irregular: ser, ir, tener, hacer, haber); after querer que, esperar que, ojalá; emotions (me alegro de que); no creo que vs creo que'),
  ('es', 'B1', 4, 'b1-relativos', 'Frasi relative', 'I pronomi relativi que, quien, donde e lo que.', 'relative pronouns que, quien, donde; lo que; preposition + el que / la que / quien'),
  ('es', 'B1', 5, 'b1-relato', 'Raccontare una storia', 'Il trapassato e le perifrasi di tempo nei racconti.', 'pretérito pluscuamperfecto; narrative tenses together; acabar de + infinitive; llevar + gerundio; desde, desde hace, hace ... que'),
  ('es', 'B1', 6, 'b1-estilo-indirecto', 'Il discorso indiretto', 'Riferire affermazioni, domande e richieste.', 'reported speech in the present and in the past (tense changes); reported questions with si and question words; reported requests with pedir / decir que + subjuntivo'),
  ('es', 'B2', 1, 'b2-hipotesis', 'Rimpianti e ipotesi', 'Il congiuntivo trapassato e il condizionale composto.', 'pluscuamperfecto de subjuntivo; condicional compuesto; si + pluscuamperfecto de subjuntivo, condicional compuesto; mixed conditionals; ojalá + imperfecto / pluscuamperfecto'),
  ('es', 'B2', 2, 'b2-subjuntivo', 'Il congiuntivo avanzato', 'Il congiuntivo dopo le congiunzioni, nelle relative e nella concordanza dei tempi.', 'aunque + indicativo or subjuntivo; para que, antes de que, sin que, a menos que + subjuntivo; subjuntivo in relative clauses (busco a alguien que sepa); imperfecto de subjuntivo and sequence of tenses'),
  ('es', 'B2', 3, 'b2-pasiva', 'La forma passiva', 'Il passivo, la passiva riflessa e il se impersonale.', 'ser + participle; pasiva refleja (se venden casas); impersonal se (se dice que, se vive bien); estar + participle for the result'),
  ('es', 'B2', 4, 'b2-perifrasis', 'Perifrasi verbali', 'Le perifrasi per l''inizio, la fine, la ripetizione e lo sviluppo di un''azione.', 'verbal periphrases: empezar a / ponerse a, dejar de, volver a, seguir + gerundio, ir + gerundio, estar a punto de'),
  ('es', 'B2', 5, 'b2-cambio', 'Ser, estar e i cambiamenti', 'Significati diversi con ser e estar e i verbi di cambiamento.', 'adjectives that change meaning with ser or estar (listo, malo, aburrido, rico); verbs of change: ponerse, quedarse, volverse, hacerse, llegar a ser'),
  ('es', 'B2', 6, 'b2-conectores', 'Collegare le idee', 'Connettivi per argomentare e scrivere testi chiari.', 'linking words for cause (ya que, puesto que, como), consequence (por lo tanto, así que, de modo que), contrast and concession (sin embargo, a pesar de, en cambio, aunque); expressing an opinion');

